import * as http from 'node:http';
function main(): void {
  const s = http.createServer((req: any, res: any) => { res.end('ok'); });
  console.log(s.listening, typeof s.timeout, s.headersTimeout, s.requestTimeout, s.keepAliveTimeout, s.maxRequestsPerSocket);
  s.listen(0, '127.0.0.1', () => {
    console.log('listening', s.listening);
    s.close(() => { console.log('closed', s.listening); });
    console.log('after close call', s.listening);
  });
}
